import{_ as o,o as a,c as s,ag as r}from"./chunks/framework.BwSLX4ak.js";const p=JSON.parse('{"title":"Music source troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"en/allmusic/troubleshooting.md","filePath":"en/allmusic/troubleshooting.md"}'),t={name:"en/allmusic/troubleshooting.md"};function i(n,e,c,u,l,h){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="music-source-troubleshooting" tabindex="-1">Music source troubleshooting <a class="header-anchor" href="#music-source-troubleshooting" aria-label="Permalink to &quot;Music source troubleshooting&quot;">​</a></h1><h2 id="music-api-not-found" tabindex="-1">Music API not found <a class="header-anchor" href="#music-api-not-found" aria-label="Permalink to &quot;Music API not found&quot;">​</a></h2><p>Put the JAR in <code>api/</code> inside AllMusic&#39;s actual data directory and restart normally. Both <code>qqmusic</code> and <code>kugou</code> are lowercase API IDs. If the logs show no successful load, resolve directory, JAR, or interface-version problems before changing <code>defaultApi</code>.</p><h2 id="nosuchmethoderror-or-classnotfoundexception" tabindex="-1">NoSuchMethodError or ClassNotFoundException <a class="header-anchor" href="#nosuchmethoderror-or-classnotfoundexception" aria-label="Permalink to &quot;NoSuchMethodError or ClassNotFoundException&quot;">​</a></h2><p>Sources depend on the AllMusic core interface. Use a matching release or put your core JAR in the extension&#39;s <code>libs/</code> and rebuild. Do not bundle AllMusic core inside the source or mix AllMusic packages for different platforms.</p><h2 id="search-works-but-playback-fails" tabindex="-1">Search works but playback fails <a class="header-anchor" href="#search-works-but-playback-fails" aria-label="Permalink to &quot;Search works but playback fails&quot;">​</a></h2><p>A search result only means a song was found. Playback also requires a valid audio URL. Check expired cookies, account permissions, and server connectivity to the music platform. Working covers or lyrics do not guarantee a playable URL. Both extensions rely on free or authorized resources returned normally by the platform.</p><h2 id="no-sound-in-the-game" tabindex="-1">No sound in the game <a class="header-anchor" href="#no-sound-in-the-game" aria-label="Permalink to &quot;No sound in the game&quot;">​</a></h2><p>Check that the player&#39;s AllMusic client mod matches the server, and that the player is not muted, blacklisted, or on an excluded server. Investigate AllMusic&#39;s own commands and playback settings before BiliMusicBridge&#39;s live connection.</p><h2 id="cookies-when-using-both-sources" tabindex="-1">Cookies when using both sources <a class="header-anchor" href="#cookies-when-using-both-sources" aria-label="Permalink to &quot;Cookies when using both sources&quot;">​</a></h2><p>QQMusic uses AllMusic&#39;s loaded cookie list. Kugou can use <code>ALLMUSIC_KUGOU_COOKIE</code> independently to reduce collisions between cookie names on different platforms. See <a href="./kugou.html#cookie-sources">Kugou cookie sources</a>.</p><h2 id="report-a-problem" tabindex="-1">Report a problem <a class="header-anchor" href="#report-a-problem" aria-label="Permalink to &quot;Report a problem&quot;">​</a></h2><p>Include the platform, Java and AllMusic versions, source version, relevant error logs, and a song identifier without account information. Report QQMusic problems to <a href="https://github.com/hutuyee/AllMusic_QQMusic/issues" target="_blank" rel="noreferrer">AllMusic_QQMusic Issues</a> and Kugou problems to <a href="https://github.com/hutuyee/AllMusic_Kugou/issues" target="_blank" rel="noreferrer">AllMusic_Kugou Issues</a>.</p>',13)])])}const m=o(t,[["render",i]]);export{p as __pageData,m as default};
